def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    distinct_strings = []  # Initialize an empty list to store the distinct strings

    start = 0
    for i in range(len(paren_string)):
        if paren_string[i] == '(':
            count = 1
            j = i + 1
            while count != 0:
                if paren_string[j] == '(':
                    count += 1
                elif paren_string[j] == ')':
                    count -= 1
                j += 1
            distinct_strings.append(paren_string[i:j])  # Separate each group into distinct strings
            start = j

    return distinct_strings
